import Foundation

/// The whole capture decision, with no `NSPasteboard` dependency so it can be
/// tested directly. `ClipboardMonitor` supplies the inputs and holds no policy.
enum ClipboardCapture {

    struct Candidate: Equatable {
        let code: String
        let language: SupportedLanguage
    }

    /// Pasteboard markers meaning "do not record this".
    ///
    /// Password managers set `ConcealedType`; `TransientType` marks values not
    /// meant to persist; `AutoGeneratedType` marks machine-produced content.
    /// Honouring all three is what keeps a password out of a capture prompt.
    static let excludedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]

    /// Written alongside the string by `Clipboard.copy`, so a copy made by
    /// Snippets is recognisable from the pasteboard alone — including by a
    /// *different* running build of the app, which cannot see this process's
    /// `Clipboard.lastLocalChangeCount`.
    static let internalCopyType = "com.halilbagosi.snippets.internal"

    /// Whether a pasteboard change was made by Snippets itself.
    ///
    /// - `isOwnWrite`: the change is the one `Clipboard.copy` just produced.
    /// - `snippetsWasFrontmost`: Snippets (any build) was the active app while
    ///   the change happened. Copies the app does not write itself — ⌘C or
    ///   Edit ▸ Copy out of a code view, a text field, a web preview — can only
    ///   come from Snippets while it is frontmost, and only those carry no
    ///   marker.
    static func isSelfOriginated(isOwnWrite: Bool, snippetsWasFrontmost: Bool) -> Bool {
        isOwnWrite || snippetsWasFrontmost
    }

    /// Whether `bundleIdentifier` names Snippets. Every build — Debug, the DMG
    /// release, side-by-side copies — shares one bundle identifier.
    static func isSnippets(bundleIdentifier: String?, ownBundleIdentifier: String?) -> Bool {
        guard let bundleIdentifier, let ownBundleIdentifier else { return false }
        return bundleIdentifier == ownBundleIdentifier
    }

    /// Stages run cheapest-rejection-first.
    static func candidate(text: String?, types: Set<String>, isOwnWrite: Bool) -> Candidate? {
        guard !isOwnWrite else { return nil }
        guard !types.contains(internalCopyType) else { return nil }
        guard types.isDisjoint(with: excludedTypes) else { return nil }
        guard let text, CodeShapeHeuristics.isLikelyCode(text) else { return nil }

        let language = LanguageDetector.detect(code: text)
        guard language != .unknown else { return nil }

        return Candidate(code: text, language: language)
    }
}
